    "title": "Day 17: Kubernetes Deployments - RollingUpdate, Recreate & Rollbacks",
    "cleanTitle": "Kubernetes Deployments - RollingUpdate, Recreate & Rollbacks",
    "duration": "1h 45m",
    "moduleId": 6,
    "moduleName": "Module 6: Kubernetes Architecture & Core Primitives",
