    "id": 21,
    "dayNum": 21,
    "title": "Day 21: Kubernetes Pod Networking & Core Services - Calico CNI, ClusterIP & NodePort",
    "cleanTitle": "Kubernetes Pod Networking & Core Services - Calico CNI, ClusterIP & NodePort",
    "duration": "1h 45m",
