    "labs": "# BASH\n# Repository Management\nhelm repo add bitnami https://charts.bitnami.com/bitnami\nhelm repo update\nhelm search repo bitnami/nginx\n\n# Chart Installation & Customization\nhelm install prod-web bitnami/nginx -n production   --set replicaCount=3   --set service.type=LoadBalancer\n\n# Inspecting Releases & History\nhelm list -n production\nhelm history prod-web -n production\n\n# Upgrading & Rolling Back\nhelm upgrade prod-web bitnami/nginx -n production --set replicaCount=5\nhelm rollback prod-web 1 -n production\n\n# Deleting a Release completely\nhelm uninstall prod-web -n production\n\n# BASH\n# Step 1: Add official Jenkins Helm repository\nhelm repo add jenkins https://charts.jenkins.io\nhelm repo update\n\n# Step 2: Create namespace\nkubectl create namespace devops\n\n# Step 3: Deploy Jenkins with customized persistence and NodePort\nhelm install jenkins-server jenkins/jenkins -n devops   --set controller.serviceType=NodePort   --set controller.nodePort=32000   --set persistence.size=10Gi\n\n# Step 4: Retrieve auto-generated Jenkins Admin Password\nkubectl exec --namespace devops -it svc/jenkins-server -c jenkins   -- /bin/cat /run/secrets/additional/chart-admin-password && echo",
